fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Only indices 0..n/2 - 1 can have children
    for i in 0..n / 2 {
        let left = 2 * i + 1;
        let right = left + 1;
        if left < n && a[left] < a[i] {
            return false;
        }
        if right < n && a[right] < a[i] {
            return false;
        }
    }
    true
}

